#include <iostream>
#include <string>
#include <regex>
#include <algorithm>
#include <cctype>

using namespace std;

int main() {
    // Read and ignore the first line (integer)
    string dummy, text;
    getline(cin, dummy);
    // Read the text to analyze
    getline(cin, text);

    // ---------- one : longest word outside parentheses ----------
    int one = 0;
    // Pattern that matches parentheses containing only letters and underscores
    regex paren(R"(\([a-zA-Z_]*\))");
    // Iterate over parts that are between such parentheses (i.e., outside)
    sregex_token_iterator it(text.begin(), text.end(), paren, -1);
    sregex_token_iterator end;
    for (; it != end; ++it) {
        string token = *it;
        // token may contain underscores -> find the longest non-underscore segment
        int cur = 0;
        size_t i = 0;
        while (i < token.length()) {
            if (token[i] != '_') {
                size_t start = i;
                while (i < token.length() && token[i] != '_')
                    ++i;
                cur = max(cur, (int)(i - start));
            } else {
                ++i;
            }
        }
        one = max(one, cur);
    }

    // ---------- two : number of words inside parentheses ----------
    int two = 0;
    bool inside = false;      // currently inside '(' ... ')'
    bool inWord = false;     // currently inside a word (only letters) while inside parentheses
    for (char c : text) {
        if (c == '(') {
            inside = true;
            inWord = false;
        } else if (c == ')') {
            inside = false;
            inWord = false;
        } else if (inside && isalpha(c)) {
            if (!inWord) {
                ++two;
                inWord = true;
            }
        } else if (inside && c == '_') {
            inWord = false;
        }
        // Other characters inside parentheses do not affect inWord
    }

    // Output the two numbers
    cout << one << " " << two << endl;
    return 0;
}
